bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env;const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
 const q=await db.query("SELECT thumbnail_file_id,sample_file_id,paid_video_file_id,price_stars,sample_duration_seconds FROM videobot_listings WHERE listing_id=(SELECT listing_id FROM videobot_post_receipts WHERE paid_message_id=$1)",[4691]);
 if(q.rowCount!==1)process.exitCode=61;
 else{
 const r=q.rows[0];
 if(!r.thumbnail_file_id||!r.sample_file_id||!r.paid_video_file_id)process.exitCode=62;
 else if(r.paid_video_file_id===r.sample_file_id || r.paid_video_file_id===r.thumbnail_file_id)process.exitCode=71;
 else if(Number(r.price_stars)!==10)process.exitCode=72;
 else if(Number(r.sample_duration_seconds)>30)process.exitCode=73;
 else console.log('PUBLIC_FREE_SAMPLE_DISTINCT_FROM_PAID_FULL_VIDEO=PASS');
 }
}catch(e){console.error('DB_CODE='+String(e?.code??'UNKNOWN').slice(0,8));process.exitCode=79}finally{await db.end()}
JS
